use super::helpers::run_prints;
fn run_c(src: &str) -> Vec<String> { run_prints(&format!("#include <stdio.h>\n{}", src)) }

#[test] fn posix_open_memstream_basic() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { char *buf; size_t size; FILE *f = open_memstream(&buf, &size); if (f) { fprintf(f, \"hello\"); fclose(f); printf(\"%s %d\", buf, (int)size); free(buf); } return 0; }"), vec!["hello 5"]); }
#[test] fn posix_open_memstream_grow() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { char *buf; size_t size; FILE *f = open_memstream(&buf, &size); if (f) { for (int i = 0; i < 100; i++) fprintf(f, \"x\"); fclose(f); printf(\"%d %c\", (int)size, buf[99]); free(buf); } return 0; }"), vec!["100 x"]); }
#[test] fn posix_open_memstream_fflush_updates() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { char *buf; size_t size; FILE *f = open_memstream(&buf, &size); if (f) { fprintf(f, \"hi\"); fflush(f); printf(\"%s %d\", buf, (int)size); fclose(f); free(buf); } return 0; }"), vec!["hi 2"]); }
#[test] fn posix_open_memstream_seek() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <stdio.h>\n#include <stdlib.h>\nint main() { char *buf; size_t size; FILE *f = open_memstream(&buf, &size); if (f) { fprintf(f, \"hello\"); fseek(f, 0, SEEK_SET); fprintf(f, \"H\"); fclose(f); printf(\"%s\", buf); free(buf); } return 0; }"), vec!["Hello"]); }
#[test] fn posix_open_wmemstream_basic() { assert_eq!(run_c("#define _POSIX_C_SOURCE 200809L\n#include <wchar.h>\n#include <stdlib.h>\n#include <stdio.h>\nint main() { wchar_t *buf; size_t size; FILE *f = open_wmemstream(&buf, &size); if (f) { fwprintf(f, L\"wide\"); fclose(f); printf(\"%d\", (int)size); free(buf); } return 0; }"), vec!["4"]); }
